    "flavorProfile": "Kuah bening berempah rempah hangat, renyahnya daging sapi goreng",
    "type": "Makanan Utama",
    "typeEn": "Main Course",
    "origin": "Kota Padang",
    "imageUrl": "/images/catalog/cu7.webp",
    "titleEn": "Soto Padang"
